void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragCoord = fract((fragCoord-5.0)/(iResolution.xy-vec2(10.0)))*(iResolution.xy-vec2(10.0))+5.0;
    vec3 me = texelFetch(iChannel0, ivec2(fragCoord), 0).rgb;
    vec3 up = texelFetch(iChannel0, ivec2(fragCoord+vec2(1.0,0.0)), 0).rgb;
    vec3 down = texelFetch(iChannel0, ivec2(fragCoord+vec2(-1.0,0.0)), 0).rgb;
    vec3 left = texelFetch(iChannel0, ivec2(fragCoord+vec2(0.0,1.0)), 0).rgb;
    vec3 right = texelFetch(iChannel0, ivec2(fragCoord+vec2(0.0,-1.0)), 0).rgb;

    vec3 col = vec3(me.x,me.y,me.z);
    if (distance(up,down)+distance(left,right)>0.1*length(me) && fragCoord.x > 1.0 && fragCoord.y > 1.0 && fragCoord.y+1.0 < iResolution.y && fragCoord.x+1.0 < iResolution.x){
    col.r = abs(col.g-max(max(left.r,right.r),max(down.r,up.r)))*(col.b*0.01+1.0);
    col.g = abs(col.b-max(max(left.b,right.b),max(down.b,up.b)))*(col.r*0.01+1.0);
    col.b = abs(col.r-max(max(left.g,right.g),max(down.g,up.g)))*(col.g*0.01+1.0);
    }
    if (iFrame < 1){
        col = texelFetch(iChannel1, ivec2(fract(fragCoord/1020.0)*1024.0), 0).rgb*5.0*texelFetch(iChannel1, ivec2(fract(fragCoord/1020.0)*1024.0), 0).rgb;
    }
    if (col.r > 10.0){
        col.r = (up.r+down.r+left.r+right.r)*0.23;
    }
    if (col.b > 10.0){
        col.b = (up.b+down.b+left.b+right.b)*0.23;
    }
    if (col.g > 10.0){
        col.g = (up.g+down.g+left.g+right.g)*0.23;
    }
    if (col.r > 20.0){
        col.r = 0.0;
    }
    if (col.b > 20.0){
        col.b = 0.0;
    }
    if (col.g > 20.0){
        col.g = 0.0;
    }

    if (iMouse.z > 0.0) {
        if (distance(fragCoord,iMouse.xy)<1.5){
            col += col*0.9+vec3(0.5);
        }
    }
    float cont = distance(col,(left+right+up+down)*0.25);
    col = (col*(1.001)-(((left+right+up+down)*0.25)*(0.001)));
    col = abs(col+10.0)-10.0;
    fragColor = vec4(col,1.0);
}
